package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("review_replies") public class ReviewReply {@Id private String id;@Indexed private String reviewId;@Indexed private String userId;private String text;private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();public String getId(){return id;}public String getReviewId(){return reviewId;}public void setReviewId(String x){reviewId=x;}public String getUserId(){return userId;}public void setUserId(String x){userId=x;}public String getText(){return text;}public void setText(String x){text=x;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setTextAndTouch(String x){text=x;updatedAt=Instant.now();}}
